edits.newText:
// B-015: show the jump glyph when either the playing track
// lives outside the browsed folder, or the now-playing row is
// currently outside the visible browser viewport; B-031
// debounces the hide.
final hasPlayingTrack =
    playingPath != null && playingPath.isNotEmpty;
final playingPathParent =
    hasPlayingTrack ? p.dirname(playingPath!) : '';
final outsideFolder = hasPlayingTrack &&
    playingPathParent != (path ?? '');
final outsideViewport = hasPlayingTrack &&
    !outsideFolder &&
    !browserController.isTrackInViewport(playingPath!);

final shouldShow = outsideFolder || outsideViewport;
if (hasPlayingTrack && !outsideFolder) {
  lastVisibilityPath.value = playingPath;
  playingTrackInViewport.value =
      browserController.isTrackInViewport(playingPath!);
} else {
  lastVisibilityPath.value = playingPath;
}

final showJumpGlyph = resolveJumpGlyphVisible(shouldShow);

